window.addEventListener('scroll',()=>scrollTarget=scrollY,{passive:true});window.addEventListener('pointermove',e=>{pointerX=(e.clientX/innerWidth-.5)*2;pointerY=(e.clientY/innerHeight-.5)*2},{passive:true});
